import sys

def solve():
    s = sys.stdin.read().strip()
    n = len(s)

    for i in range(n + 1):
        for char_code in range(ord('a'), ord('z') + 1):
            c = chr(char_code)
            candidate = s[:i] + c + s[i:]
            if candidate == candidate[::-1]:
                print(candidate)
                return

    print("NA")

if __name__ == "__main__":
    solve()
